    """

    version: int
    hash_name: str
    size: int
    root: bytes
    head: bytes
    retain_from: int
    pointers: tuple
    items: tuple
    proof: tuple
    groups: tuple

    def __post_init__(self) -> None:
        if not isinstance(self.version, int) or isinstance(self.version, bool):
            raise TypeError("version must be an integer")
        if self.version != _JSON_MULTI_INDEX_VERSION:
            raise ValueError("version must be 1")
        if not isinstance(self.hash_name, str):
            raise TypeError("hash_name must be a string")
        digest_size = _digest_size(self.hash_name)
        for name in ("size", "retain_from"):
            bound = getattr(self, name)
            if not isinstance(bound, int) or isinstance(bound, bool):
                raise TypeError(f"{name} must be an integer")
        if not 0 <= self.size < _U64_LIMIT:
            raise ValueError("size must satisfy 0 <= size < 2**64")
        if not 0 <= self.retain_from <= self.size:
            raise ValueError(
                "retain_from must satisfy 0 <= retain_from <= size"
            )
        for name in ("root", "head"):
            value = getattr(self, name)
            if not isinstance(value, bytes):
                raise TypeError(f"{name} must be bytes")
            if len(value) != digest_size:
                raise ValueError(f"{name} must be {digest_size} bytes")
        if not isinstance(self.pointers, tuple):
            raise TypeError("pointers must be a tuple of strings")
        if not self.pointers:
            raise ValueError("pointers must be a non-empty tuple")
        canonical_pointers: list[str] = []
        for pointer in self.pointers:
            if not isinstance(pointer, str):
                raise TypeError("pointer must be a string")
            tokens = _parse_json_pointer(pointer)
            canonical_pointers.append(_json_pointer_canonical(tokens))
        for earlier, later in zip(canonical_pointers, canonical_pointers[1:]):
            if not later > earlier:
                raise ValueError(
                    "pointers must be unique and in strictly ascending order"
                )
        if tuple(canonical_pointers) != self.pointers:
            object.__setattr__(self, "pointers", tuple(canonical_pointers))
        if not isinstance(self.items, tuple):
            raise TypeError("items must be a tuple of Entry records")
        expected_index = self.retain_from
        for entry in self.items:
            if not isinstance(entry, Entry):
                raise TypeError("item must be an Entry")
            if not isinstance(entry.index, int) or isinstance(entry.index, bool):
                raise TypeError("entry.index must be an integer")
            for name in ("payload", "previous_hash", "entry_hash"):
                if not isinstance(getattr(entry, name), bytes):
                    raise TypeError(f"entry.{name} must be bytes")
            if len(entry.previous_hash) != digest_size:
                raise ValueError(f"entry.previous_hash must be {digest_size} bytes")
            if len(entry.entry_hash) != digest_size:
                raise ValueError(f"entry.entry_hash must be {digest_size} bytes")
            if entry.index != expected_index:
                raise ValueError(
                    "items must carry every covered entry in ascending order "
                    f"[retain_from ({self.retain_from}), size ({self.size}))"
                )
            expected_index += 1
        if len(self.items) != self.size - self.retain_from:
            raise ValueError(
                "items must carry every entry of [retain_from, size)"
            )
        if not isinstance(self.proof, tuple):
            raise TypeError("proof must be a tuple of digests")
        for node in self.proof:
            if not isinstance(node, bytes):
                raise TypeError("proof element must be bytes")
            if len(node) != digest_size:
                raise ValueError(f"proof element must be {digest_size} bytes")
        if not self.items and self.proof:
            raise ValueError("an empty coverage index must carry an empty proof")
        if not isinstance(self.groups, tuple):
            raise TypeError("groups must be a tuple aligned with pointers")
        if len(self.groups) != len(self.pointers):
            raise ValueError("groups must carry one group tuple per pointer")
        for pointer_groups in self.groups:
            if not isinstance(pointer_groups, tuple):
                raise TypeError(
                    "each pointer's groups must be a tuple of "
                    "JsonSearchIndexGroup"
                )
            seen_kinds: list[int] = []
            assigned: dict[int, tuple[int, bytes]] = {}
            for group in pointer_groups:
                if not isinstance(group, JsonSearchIndexGroup):
                    raise TypeError("group must be a JsonSearchIndexGroup")
                # Re-validate the group even for one built bypassing its
                # constructor, so structural corruption raises exactly as
                # the group constructor would.
                JsonSearchIndexGroup(group.kind, group.buckets)
                if seen_kinds and group.kind <= seen_kinds[-1]:
                    raise ValueError(
                        "groups must be unique and in ascending kind order"
                    )
                seen_kinds.append(group.kind)
                for bucket in group.buckets:
                    for index in bucket.hits:
                        if not self.retain_from <= index < self.size:
                            raise ValueError(
                                f"bucket hit {index} must satisfy retain_from "
                                f"({self.retain_from}) <= index < size "
                                f"({self.size})"
                            )
                        if index in assigned:
                            raise ValueError(
                                "entry "
                                f"{index} is assigned to more than one bucket"
                            )
                        assigned[index] = (group.kind, bucket.key)

    def _range_bounds(self, start: Any, stop: Any) -> tuple[int, int]:
        """Validate a :meth:`find` half-open range exactly like find_json."""
        first = self.retain_from
        last = self.size
        if start is None:
            start = first
        elif not isinstance(start, int) or isinstance(start, bool):
            raise TypeError("start must be an integer")
        if stop is None:
            stop = last
        elif not isinstance(stop, int) or isinstance(stop, bool):
            raise TypeError("stop must be an integer")
        if not first <= start <= stop <= last:
            raise ValueError(
                f"range must satisfy retain_from ({first}) <= start <= stop "
                f"<= size ({last})"
            )
        return start, stop

    def find(
        self,
        pointer: Any,
        value: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer a find_json scalar-equality query from the frozen index.

        ``pointer`` must be one of the index's bound pointers (its
        canonical RFC 6901 spelling); the accepted ``value`` types, the
        JSON kind-separated comparison (strings, booleans and null match
        only their own kind; ints and floats are both JSON numbers and
        compare by numeric value), the half-open ``[start, stop)`` range
        defaults and bounds, and the strictly ascending absolute-index
        result order are exactly those of :meth:`AuditLog.find_json` over
        the index's covered snapshot. A non-``str`` or malformed pointer
        raises TypeError/ValueError as in :meth:`AuditLog.find_json`, and a
        pointer the index was not built for raises ValueError; a value of
        another type raises TypeError; a non-finite float or an
        out-of-range bound raises ValueError and a wrong bound type
        TypeError. The lookup is read-only and never mutates the index.
        """
        tokens = _parse_json_pointer(pointer)
        canonical = _json_pointer_canonical(tokens)
        try:
            position = self.pointers.index(canonical)
        except ValueError as error:
            raise ValueError(
                f"pointer {canonical!r} is not covered by this index"
            ) from error
        _check_json_value(value)
        start, stop = self._range_bounds(start, stop)
        merged = _json_groups_find_all(self.groups[position], value)
        return tuple(index for index in merged if start <= index < stop)

    def find_all(
        self,
        conditions: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer several find_json equality conditions in one lookup.

        ``conditions`` is a tuple of ``(pointer, value)`` pairs, each
        following exactly the rules of :meth:`find`: the pointer must be a
        canonical RFC 6901 spelling bound by this index and ``value`` a
        JSON scalar (``str``, ``int``, finite ``float``, ``bool`` or
        ``None``) with the same kind-separated comparison — strings,
        booleans and null match only their own kind while ints and floats
        compare by numeric value. The conditions need no ordering and a
        pointer may repeat; only entries satisfying *every* condition
        within the half-open ``[start, stop)`` range are returned, as a
        tuple of absolute indices in strictly ascending order without
        duplicates (``()`` when nothing matches). Repeating an identical
        condition never changes the result, and mutually exclusive
        conditions on one pointer yield ``()``. An empty ``conditions``
        tuple imposes no field constraint and returns every index in the
        range.

        Non-JSON, encrypted, missing-field and non-scalar targets never
        satisfy the corresponding condition, exactly as for :meth:`find`.
        A non-tuple ``conditions`` or condition, a wrong-typed pointer or
        value, or a wrong-typed range bound raises TypeError; a condition
        tuple whose length is not two, a malformed pointer, a pointer the
        index was not built for, a non-finite float, or an out-of-range or
        reversed range raises ValueError. Every condition and the range
        are validated before any lookup, so such an error is reported
        even when an earlier condition already has no hit or the range is
        empty. The lookup is read-only and never mutates the index.
        """
        if not isinstance(conditions, tuple):
            raise TypeError(
                "conditions must be a tuple of (pointer, value) pairs"
            )
        resolved: list[tuple[int, Any]] = []
        for condition in conditions:
            if not isinstance(condition, tuple):
                raise TypeError("each condition must be a (pointer, value) tuple")
            if len(condition) != 2:
                raise ValueError("each condition must have exactly two items")
            pointer, value = condition
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_value(value)
            resolved.append((position, value))
        start, stop = self._range_bounds(start, stop)
        if not resolved:
            return tuple(range(start, stop))
        result: tuple[int, ...] | None = None
        for position, value in resolved:
            merged = _json_groups_find_all(self.groups[position], value)
            hits = tuple(index for index in merged if start <= index < stop)
            if result is None:
                result = hits
            else:
                result = _intersect_ascending_tuples(result, hits)
            if not result:
                break
        return tuple(() if result is None else result)

    def _resolve_where_expression(self, expression: Any) -> tuple:
        """Validate a :meth:`find_where` expression and resolve pointers.

        Returns a parallel tree with every leaf pointer replaced by its
        position in ``self.pointers``. Validation is pre-order: a node's
        own errors are reported before its children's, and children are
        checked from left to right.
        """
        if not isinstance(expression, tuple):
            raise TypeError("expression nodes must be tuples")
        if not expression:
            raise ValueError("expression node must not be empty")
        operator = expression[0]
        if not isinstance(operator, str):
            raise TypeError("expression operator must be a string")
        if operator == "eq":
            if len(expression) != 3:
                raise ValueError('an "eq" node must have exactly three items')
            _, pointer, value = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_value(value)
            return ("eq", position, value)
        if operator in ("lt", "le", "gt", "ge"):
            if len(expression) != 3:
                raise ValueError(
                    f'a "{operator}" node must have exactly three items'
                )
            _, pointer, threshold = expression
            tokens = _parse_json_pointer(pointer)
            canonical = _json_pointer_canonical(tokens)
            try:
                position = self.pointers.index(canonical)
            except ValueError as error:
                raise ValueError(
                    f"pointer {canonical!r} is not covered by this index"
                ) from error
            _check_json_threshold(threshold)
            return (operator, position, threshold)
        if operator in ("and", "or"):
            if len(expression) != 2:
                raise ValueError(
                    f'an "{operator}" node must have exactly two items'
                )
            children = expression[1]
            if not isinstance(children, tuple):
                raise TypeError(f'"{operator}" children must be a tuple')
            return (
                operator,
                tuple(
                    self._resolve_where_expression(child) for child in children
                ),
            )
        if operator == "not":
            if len(expression) != 2:
                raise ValueError('"not" node must have exactly two items')
            return ("not", self._resolve_where_expression(expression[1]))
        raise ValueError(f"unknown expression operator {operator!r}")

    def _evaluate_where_expression(
        self, node: tuple, start: int, stop: int
    ) -> tuple[int, ...]:
        """Evaluate a resolved :meth:`find_where` tree over [start, stop)."""
        operator = node[0]
        if operator == "eq":
            merged = _json_groups_find_all(self.groups[node[1]], node[2])
            return tuple(index for index in merged if start <= index < stop)
        if operator in ("lt", "le", "gt", "ge"):
            merged = _json_groups_find_range(
                self.groups[node[1]], operator, node[2]
            )
            return tuple(index for index in merged if start <= index < stop)
        if operator == "and":
            children = node[1]
            if not children:
                return tuple(range(start, stop))
            result: tuple[int, ...] | None = None
            for child in children:
                hits = self._evaluate_where_expression(child, start, stop)
                if result is None:
                    result = hits
                else:
                    result = _intersect_ascending_tuples(result, hits)
                if not result:
                    break
            return tuple(() if result is None else result)
        if operator == "or":
            return _union_ascending_tuples(
                tuple(
                    self._evaluate_where_expression(child, start, stop)
                    for child in node[1]
                )
            )
        # "not": complement over every index of the query range.
        hits = self._evaluate_where_expression(node[1], start, stop)
        return _complement_ascending_tuple(hits, start, stop)

    def find_where(
        self,
        expression: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Answer a nested boolean query of find_json equality leaves.

        ``expression`` is a tuple tree. A leaf is ``("eq", pointer,
        value)`` and follows exactly the rules of :meth:`find`: the
        pointer must be a canonical RFC 6901 spelling bound by this index
        and ``value`` a JSON scalar (``str``, ``int``, finite ``float``,
        ``bool`` or ``None``) with the same kind-separated comparison —
        strings, booleans and null match only their own kind while ints
        and floats compare by numeric value. A numeric-comparison leaf is
        ``("lt", pointer, threshold)``, ``("le", pointer, threshold)``,
        ``("gt", pointer, threshold)`` or ``("ge", pointer, threshold)``
        with the same pointer rules; ``threshold`` must be a non-boolean
        ``int`` or a finite ``float`` and the addressed JSON number
        compares against it by exact numeric value across the integer
        and float kinds — big integers never round to a nearby float and
        negative zero equals positive zero. A combination is
        ``("and", children)``, ``("or", children)`` or ``("not", child)``
        where ``children`` is a tuple of sub-expressions that may nest
        recursively. ``and`` intersects its children's hits, ``or`` takes
        their union and ``not`` complements its child against every index
        of the query range. An empty ``and`` returns the whole range, an
        empty ``or`` returns ``()``, a double negation restores the
        original hits and repeating a branch never adds duplicate hits.
        The result is a tuple of absolute indices in strictly ascending
        order without duplicates (``()`` when nothing matches), clipped
        to the half-open ``[start, stop)`` range with the same defaults
        and bounds as :meth:`find`; an empty range yields ``()``.

        Non-JSON, encrypted, missing-field and non-scalar targets never
        satisfy an ``eq`` leaf — a missing field is not ``null`` — and
        non-numeric targets (booleans, strings, null, objects and arrays)
        never satisfy a numeric-comparison leaf, so all of them do
        satisfy that leaf's negation, exactly as for :meth:`find`. A
        non-tuple node or ``children``, a non-string operator or pointer,
        a value or threshold of another type, or a wrong-typed range
        bound raises TypeError; an empty node, an unknown operator, a
        node of the wrong length, a malformed or uncovered pointer, a
        non-finite float value or threshold, or an out-of-range or
        reversed range raises ValueError. The whole expression is
        validated before any lookup — a node's own errors before its
        children's, children from left to right, the range last — so an
        empty range or an already determined intermediate result never
        masks an invalid branch. The lookup is read-only and never
        mutates the index.
        """
        resolved = self._resolve_where_expression(expression)
        start, stop = self._range_bounds(start, stop)
        return self._evaluate_where_expression(resolved, start, stop)


@dataclass(frozen=True)
class SignedJsonMultiIndex:
    """Persistent multi-pointer JSON index sealed by a trusted Ed25519 key.

    Bundles the :class:`JsonMultiIndex` of
    :meth:`AuditLog.signed_json_multi_index` with a 64-byte Ed25519
    signature over a domain-separated message embedding the index's whole
    canonical encoding (:func:`encode_json_multi_index`), so the
    signature binds the ordered pointer tuple, the hash algorithm,
    snapshot ``size``, Merkle root, chain head, retain point, the complete
    covered entry set, the shared proof and every pointer's hit sets. An
    offline receiver holding only a pre-trusted 32-byte Ed25519 public key
    confirms coverage, the complete hit sets and the signature with
    :func:`verify_signed_json_multi_index` — no :class:`AuditLog`
    required — then answers repeated :meth:`find` queries offline.

    Instances are immutable, may be built positionally and compare by both
    fields. ``index`` must be a :class:`JsonMultiIndex` and ``signature``
    exact 64-byte ``bytes`` (``bytearray`` / ``memoryview`` are rejected);
    whether the signature is genuine is left to
    :func:`verify_signed_json_multi_index`.
    """

    index: JsonMultiIndex
    signature: bytes

    def __post_init__(self) -> None:
        if not isinstance(self.index, JsonMultiIndex):
            raise TypeError("index must be a JsonMultiIndex")
        if not isinstance(self.signature, bytes):
            raise TypeError("signature must be bytes")
        if len(self.signature) != _ED25519_SIGNATURE_BYTES:
            raise ValueError(
                f"signature must be {_ED25519_SIGNATURE_BYTES} bytes"
            )

    @property
    def pointers(self) -> tuple:
        return self.index.pointers

    def find(
        self,
        pointer: Any,
        value: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Find on the bundled :class:`JsonMultiIndex`; semantics identical."""
        return self.index.find(pointer, value, start, stop)

    def find_all(
        self,
        conditions: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Multi-condition find on the bundled index; semantics identical."""
        return self.index.find_all(conditions, start, stop)

    def find_where(
        self,
        expression: Any,
        start: int | None = None,
        stop: int | None = None,
    ) -> tuple[int, ...]:
        """Nested boolean find on the bundled index; semantics identical."""
        return self.index.find_where(expression, start, stop)


@dataclass(frozen=True)
class SignedRangeSearchReceipt:
    """Range-search completeness receipt sealed by a pre-trusted Ed25519 key.
    Bundles a :class:`RangeSearchReceipt` with a 64-byte Ed25519 signature
    over a domain-separated message embedding the receipt's whole canonical
    encoding (:func:`encode_range_search_receipt`), so the signature binds
    every receipt field — both interval bounds, the index range, the
    complete entry set and the shared proof — together with the snapshot
    Merkle root. An offline receiver holding only a pre-trusted 32-byte
    Ed25519 public key can therefore confirm with
    :func:`verify_signed_range_search_receipt` that the whole artifact was
    issued by the log holder, without holding the :class:`AuditLog`.

    - ``receipt``: the :class:`RangeSearchReceipt` produced by
      :meth:`AuditLog.range_search_receipt`,
    - ``signature``: the 64-byte Ed25519 signature over
      ``D || 0x01 || B(encode_range_search_receipt(receipt))`` with
      ``D = b"auditchain/signed-range-search/v1\\0"``.

    Instances are immutable, may be built positionally and compare by both
    fields. ``receipt`` must be a :class:`RangeSearchReceipt` and
    ``signature`` exact 64-byte ``bytes`` — wrong field types raise
    TypeError and a wrong signature width ValueError. Whether the signature
    is genuine is left to :func:`verify_signed_range_search_receipt`.
    """

    receipt: RangeSearchReceipt
    signature: bytes

    def __post_init__(self) -> None:
        if not isinstance(self.receipt, RangeSearchReceipt):
            raise TypeError("receipt must be a RangeSearchReceipt")
        if not isinstance(self.signature, bytes):
            raise TypeError("signature must be bytes")
        if len(self.signature) != _ED25519_SIGNATURE_BYTES:
            raise ValueError(
                f"signature must be {_ED25519_SIGNATURE_BYTES} bytes"
            )


@dataclass(frozen=True)
class BatchInclusionProof:
    """Offline credential binding a compact batch inclusion proof to its context.

    Ties everything :func:`verify_batch_inclusion` needs into one artifact, so
    a proof minted by :meth:`AuditLog.batch_inclusion_proof` can be persisted
    and restored in another process without re-holding the log:

    - ``hash_name``: hash algorithm of the log the proof came from,
    - ``indices``: strictly ascending tuple of the selected absolute indices,
    - ``entry_hashes``: tuple of the selected entries' digests, exactly as
      long as ``indices``,
    - ``size``: number of entries in the snapshot the proof refers to,
    - ``root``: Merkle root of that snapshot,
    - ``proof``: the shared proof node tuple, in generation order.

    Instances are immutable, may be built positionally and compare by all six
    fields. Whether the proof node count fits the selected leaves and whether
    the nodes rebuild ``root`` is left to :func:`verify_batch_inclusion`: a
    wrong node count raises ValueError there and a mere content mismatch
    returns False; the constructor only fixes the shape, widths and ordering.
    """

    hash_name: str
    indices: tuple[int, ...]
    entry_hashes: tuple[bytes, ...]
    size: int
    root: bytes
    proof: tuple[bytes, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.hash_name, str):
            raise TypeError("hash_name must be a string")
        digest_size = _digest_size(self.hash_name)

        if not isinstance(self.indices, tuple):
            raise TypeError("indices must be a tuple of integers")
        if not self.indices:
            raise ValueError("indices must be non-empty")
        previous = -1
        for index in self.indices:
            if not isinstance(index, int) or isinstance(index, bool):
                raise TypeError("indices must be non-bool integers")
            if index < 0:
                raise ValueError("indices must be non-negative")
            if index <= previous:
                raise ValueError(
                    "indices must be strictly ascending with no duplicates"
                )
            previous = index

        if not isinstance(self.entry_hashes, tuple):
            raise TypeError("entry_hashes must be a tuple of digests")
        if len(self.entry_hashes) != len(self.indices):
            raise ValueError("entry_hashes must have the same length as indices")
        for entry_hash in self.entry_hashes:
            if not isinstance(entry_hash, bytes):
                raise TypeError("entry_hashes elements must be bytes")
            if len(entry_hash) != digest_size:
                raise ValueError(f"entry_hash must be {digest_size} bytes")

        if not isinstance(self.size, int) or isinstance(self.size, bool):
            raise TypeError("size must be a non-bool integer")
        if self.size <= 0:
            raise ValueError("size must be positive")
        if self.size >= _U64_LIMIT:
            raise ValueError("size must satisfy size < 2**64")
        if self.indices[-1] >= self.size:
            raise ValueError(
                f"index {self.indices[-1]} must satisfy "
                f"0 <= index < size ({self.size})"
            )

        # root and every proof node must be exact bytes: bytearray and
        # memoryview are rejected rather than copied, so a received credential
        # never silently aliases a mutable caller buffer.
        if not isinstance(self.root, bytes):
            raise TypeError("root must be bytes")
        if len(self.root) != digest_size:
            raise ValueError(f"root must be {digest_size} bytes")

        if not isinstance(self.proof, tuple):
            raise TypeError("proof must be a tuple of digests")
        for node in self.proof:
            if not isinstance(node, bytes):
                raise TypeError("proof elements must be bytes")
            if len(node) != digest_size:
                raise ValueError(f"proof element must be {digest_size} bytes")


@dataclass(frozen=True)
class InclusionProof:
    """Offline credential binding a single-entry inclusion proof to its context.

    Ties everything :func:`verify_inclusion` needs into one artifact, so a
    proof minted by :meth:`AuditLog.inclusion_proof` can be persisted and
    restored in another process without re-holding the log:

    - ``hash_name``: hash algorithm of the log the proof came from,
    - ``index``: absolute index of the proven entry within the snapshot,
    - ``size``: number of entries in the snapshot the proof refers to,
    - ``entry_hash``: digest of the proven entry,
    - ``root``: Merkle root of that snapshot,
    - ``proof``: the sibling-node tuple, in generation order.

    Instances are immutable, may be built positionally and compare by all six
    fields. Whether the proof node count fits the leaf and whether the nodes
    rebuild ``root`` is left to :func:`verify_inclusion`: a wrong node count
    raises ValueError there and a mere content mismatch returns False; the
    constructor only fixes the types, widths and ranges.
    """

    hash_name: str
    index: int
    size: int
    entry_hash: bytes
    root: bytes
    proof: tuple[bytes, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.hash_name, str):
            raise TypeError("hash_name must be a string")
        digest_size = _digest_size(self.hash_name)

        if not isinstance(self.index, int) or isinstance(self.index, bool):
            raise TypeError("index must be a non-bool integer")
        if self.index < 0:
            raise ValueError("index must be non-negative")

        if not isinstance(self.size, int) or isinstance(self.size, bool):
